class WeldDataLog(GeneratedModel):
    """
      Represents a single action taken by a user while filling a webform within a Workflow. For
    example, a `WeldDataLog` object will be created when a user completes a webform, downloads
    a file, voids the packet associated packet, etc.

    All actions with a short description:

    ```md
    accessed: Viewed
    archived: Archived
    completed: Completed Form
    created: Created
    download-csv-all: Downloaded
    download-csv-individual-file: Downloaded
    download-file-individual: Downloaded File
    download-files-zip: Downloaded Zip
    emailed-completed: Emailed
    emailed: Emailed
    locked: Locked
    pin-code-changed: Changed PIN
    pin-code-failed: Access Failed
    pin-code-set: Set PIN
    pin-code-unset: Unset PIN
    pin-code-verified: Access Verified
    saved-form: Saved form
    signed: Signed
    unarchived: Unarchived
    unlocked: Unlocked
    upload-file-accessed: Accessed file
    upload-file: Uploaded
    voided: Voided
    ```
    """

    model_config = ConfigDict(
        extra="allow",
        populate_by_name=True,
    )
    action: Annotated[String | None, Field(description="The action taken.")] = None
    created_at: Annotated[Date | None, Field(alias="createdAt")] = None
    eid: Annotated[
        String | None, Field(description="The `eid` is the object identifier.")
    ] = None
    formatted_location: Annotated[
        String | None,
        Field(
            alias="formattedLocation",
            description="Location of the user taking the action.",
        ),
    ] = None
    id: Int
    metadata: Annotated[Any, Field(description="Any action-specific information.")] = (
        None
    )
    submission: Submission | None = None
    user: Annotated[
        User | None,
        Field(description="The Anvil `User` who took this action, if applicable."),
    ] = None
    weld_data: Annotated[WeldData | None, Field(alias="weldData")] = None


